import React, { useState, useEffect } from "react";
import "./chat.css";
import fever from "./assets/symptom/fever.png";
import cough from "./assets/symptom/cough.png";
import backPain from "./assets/symptom/backPain.png";
import drizziness from "./assets/symptom/drizziness.png";
import fatigue from "./assets/symptom/fatigue.png";
import chestPain from "./assets/symptom/chestPain.png";

function Chatbot() {
  const [text, setText] = useState("");
  const [chat, setChat] = useState([]);
  const [recording, setRecording] = useState(false);
  const [mediaRecorder, setMediaRecorder] = useState(null);
  const [isTyping, setIsTyping] = useState(false);
  const [typingDots, setTypingDots] = useState("...");

  // 🩺 Default symptom image list
  const symptomImages = [
    { name: "Fever", file: fever },
    { name: "Cough", file: cough },
    { name: "Fatigue", file: fatigue },
    { name: "Dizziness", file: drizziness },
    { name: "Chest pain", file: chestPain },
    { name: "Back pain", file: backPain },
  ];

  // 🕓 Typing dots animation
  useEffect(() => {
    if (!isTyping) return;
    const interval = setInterval(() => {
      setTypingDots((prev) => (prev.length >= 3 ? "." : prev + "."));
    }, 500);
    return () => clearInterval(interval);
  }, [isTyping]);

  // ✉️ Send text to backend
  const handleSend = async (inputText) => {
    const userInput = inputText || text;
    if (!userInput.trim()) return;

    const userMsg = { sender: "user", text: userInput };
    setChat((prev) => [...prev, userMsg]);
    setText("");
    setIsTyping(true);

    try {
      const res = await fetch("/api/match", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ text: userInput }),
      });
      const data = await res.json();

      // build predictions text with scores
      const predictionsWithText = (data.predictions || []).map((p) => {
        let possibility = "";
        if (p.score < 0.4) possibility = "Low";
        else if (p.score < 0.7) possibility = "Medium";
        else possibility = "High";
        return { ...p, possibility };
      });

      // Combine everything into a full message text
      let fullText = "";
      fullText += data.message || "It sounds like you might be experiencing:\n";

      if (data.symptoms?.length) {
        fullText += `\n Detected Symptoms: ${data.symptoms.join(", ")}\n`;
      }

      if (predictionsWithText.length > 0) {
        fullText += "\n Possible Diseases:\n";
        predictionsWithText.forEach((p) => {
          fullText += `- ${p.disease} — score: ${p.score} | Possibility: ${p.possibility}\n`;
        });
      }

      // show "Assistant is typing" first
      setIsTyping(true);

      setTimeout(() => {
        setIsTyping(false);
        const botMsg = { sender: "bot", text: "" };
        setChat((prev) => [...prev, botMsg]);

        // 🧠 Typing animation
        const typingSpeed = 25; // ms per character
        let i = 0;
        const interval = setInterval(() => {
          i++;
          setChat((prev) => {
            const updated = [...prev];
            updated[updated.length - 1].text = fullText.slice(0, i);
            return updated;
          });
          if (i >= fullText.length) clearInterval(interval);
        }, typingSpeed);
      }, 3000 + Math.random() * 1000); // delay before typing starts
    } catch (err) {
      console.error("Error:", err);
      setIsTyping(false);
    }
  };

  // 🎙️ Start voice recording
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      const chunks = [];

      recorder.ondataavailable = (e) => chunks.push(e.data);
      recorder.onstop = async () => {
        const blob = new Blob(chunks, { type: "audio/webm" });
        const formData = new FormData();
        formData.append("file", blob, "voice.webm");

        const userMsg = { sender: "user", text: "🎤 Voice message..." };
        setChat((prev) => [...prev, userMsg]);
        setIsTyping(true);

        const res = await fetch("/api/voice", {
          method: "POST",
          body: formData,
        });
        const data = await res.json();

        const predictionsWithText = (data.predictions || []).map((p) => {
          let possibility = "";
          if (p.score < 0.4) {
            possibility = "Low";
          } else if (p.score < 0.7) {
            possibility = "Medium";
          } else {
            possibility = "High";
          }
          return { ...p, possibility };
        });

        const botMsg = {
          sender: "bot",
          text:
            data.message ||
            "I’ve analyzed your voice input. Here’s what I found:",
          symptoms: data.symptoms || [],
          predictions: predictionsWithText,
        };

        const delay = 3000 + Math.random() * 1000;
        setTimeout(() => {
          setChat((prev) => [...prev, botMsg]);
          setIsTyping(false);
        }, delay);
      };

      recorder.start();
      setMediaRecorder(recorder);
      setRecording(true);
    } catch (err) {
      console.error("Microphone error:", err);
      alert("Microphone not available or permission denied.");
    }
  };

  // ⏹ Stop voice recording
  const stopRecording = () => {
    if (mediaRecorder) {
      mediaRecorder.stop();
      setRecording(false);
    }
  };

  return (
    <div className="chatbot-container">
      <h2 className="chatbot-title">🩺 Smart Clinical Assistant</h2>

      <div className="chat-box">
        {/* 🖼️ Default image picker */}
        {chat.length === 0 && (
          <div className="symptom-gallery">
            <p className="gallery-text">Choose a symptom to begin:</p>
            <div className="gallery-grid">
              {symptomImages.map((sym, i) => (
                <div
                  key={i}
                  className="symptom-card"
                  onClick={() => handleSend(sym.name)}
                >
                  <img src={sym.file} alt={sym.name} className="symptom-img" />
                </div>
              ))}
            </div>
            <p className="gallery-text">
              Or chat with our health assistant below.
            </p>
          </div>
        )}

        {/* 💬 Chat messages */}
        {chat.map((msg, idx) => (
          <div
            key={idx}
            className={`chat-message ${msg.sender === "user" ? "user" : "bot"}`}
          >
            <div className="message-bubble">
              <div>{msg.text}</div>
              {msg.predictions?.length > 0 && (
                <div className="message-details">
                  {msg.symptoms?.length > 0 && (
                    <p>
                      <b>Detected Symptoms:</b> {msg.symptoms.join(", ")}
                    </p>
                  )}
                  {msg.predictions.map((p, i) => (
                    <p key={i}>
                      <b>{p.disease}</b> — score: {p.score}
                      <br></br>
                      <b>Possibility: </b>
                      {p.possibility}
                    </p>
                  ))}
                </div>
              )}
            </div>
          </div>
        ))}

        {isTyping && (
          <div className="typing-indicator">
            <span>Assistant is thinking</span>
            <div className="typing-dot"></div>
            <div className="typing-dot"></div>
            <div className="typing-dot"></div>
          </div>
        )}
      </div>

      {/* Input Section */}
      <div className="input-section">
        <input
          type="text"
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Describe your symptoms..."
          className="chat-input"
          onKeyDown={(e) => e.key === "Enter" && handleSend()}
        />
        <button onClick={() => handleSend()} className="btn-send">
          Send
        </button>
        <button
          onClick={recording ? stopRecording : startRecording}
          className={`btn-mic ${recording ? "recording" : ""}`}
        >
          {recording ? "Stop" : "🎤 Mic"}
        </button>
      </div>
    </div>
  );
}

export default Chatbot;
